'use strict';

import { createError, MISSING_DOC } from 'pouchdb-errors';

import { META_STORE } from './util';

export default function (txn, doc, callback) {
  if (txn.error) {
    return callback(txn.error);
  }

  const id = doc._id;

  txn.txn.objectStore(META_STORE).delete(id).onsuccess = function (e) {
    const oldDoc = e.target.result;
    if (!oldDoc || oldDoc._rev !== doc._rev) {
      callback(createError(MISSING_DOC));
    } else {
      callback(null, {ok: true, id: id, rev: '0-0'});
    }
  };
}
